/*
 * Asignación a columnas de Postgres.
 *
 * `chofer` puede llegar como 'SIN ASIGNACION': lo escribe la propia consulta
 * cuando el seller no tuvo ninguna colecta en la ventana. Se guarda tal cual
 * en vez de pasarlo a nulo, porque es un estado que la operación mira —son los
 * sellers que hay que repartir— y no un dato faltante.
 */
const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};
const entero = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

return $input.all().map(({ json: r }) => ({
  json: {
    id_usuario: Number(r.IdUsuario),
    seller: texto(r.Seller),
    lugar_colecta: texto(r.LugarColecta),
    id_motoboy: texto(r.IdMotoboy),
    chofer: texto(r.Chofer),
    cantidad_colectas: entero(r.CantidadColectas),
    cantidad_historica: entero(r.CantidadHistorica),
    actualizado_en: new Date().toISOString(),
  },
})).filter((i) => Number.isFinite(i.json.id_usuario) && i.json.id_usuario > 0);
